new file mode 100644
index 0000000..35aac4a
--- /dev/null
+++ b/src/domain/access.js
@@ -0,0 +1,25 @@
+import { AppError } from "../errors.js";
+
+const cookPaths = [
+  /^\/recipes\/[^/]+\/cook$/,
+  /^\/batches\/[^/]+\/waste$/,
+  /^\/temperatures$/,
+  /^\/stocktakes\/[^/]+\/counts$/,
+];
+
+/** Finds the API key supplied in a Bearer authorization header. */
+export function authenticate(store, headers) {
+  const header = Object.entries(headers).find(([name]) => name.toLowerCase() === "authorization")?.[1];
+  const match = typeof header === "string" ? /^Bearer ([^\s]+)$/i.exec(header) : null;
+  const key = match && store.data.apiKeys.find((entry) => entry.key === match[1]);
+  if (!key) throw new AppError("unauthorized");
+  return key;
+}
+
+/** Checks whether a key's role permits the requested operation. */
+export function authorize(key, method, path) {
+  if (key.role === "manager") return;
+  if ((key.role === "viewer" || key.role === "cook") && method === "GET" && path !== "/audit") return;
+  if (key.role === "cook" && method === "POST" && cookPaths.some((pattern) => pattern.test(path))) return;
+  throw new AppError("forbidden");
+}
