@@ -0,0 +1,9 @@
+/** Appends the metadata for a successful data-changing request. */
+export function appendAudit(store, entry) {
+  store.data.audit.push({ ...entry });
+}
+
+/** Lists audit entries newest first, including reverse insertion order for ties. */
+export function listAudit(store) {
+  return store.data.audit.slice().reverse().sort((a, b) => b.time.localeCompare(a.time));
+}
